//
//  ThemeCatalog.swift
//  GuacTerm
//
//  The built-in color schemes offered in Settings › Appearance.
//
//  The catalog is the two hand-written signature themes followed by the
//  vendored iTerm2-Color-Schemes collection (Resources/Themes.json, generated by
//  scripts/generate-themes.py). Loading lives in ThemeCatalogLoader.swift.
//

extension TerminalTheme {

    // MARK: - Signature themes

    /// GuacTerm's own dark scheme. Also the fallback for unknown identifiers
    /// (see `TerminalTheme.defaultThemeID`).
    static let guac = TerminalTheme(
        id: "guac",
        name: "Guac",
        isLight: false,
        background: "#0B1410",
        foreground: "#E8E4D9",
        cursor: "#9BE564",
        ansi: [
            "#10201A", // 0 black
            "#E06C75", // 1 red
            "#7FC96B", // 2 green
            "#E3C87A", // 3 yellow
            "#6DA8E0", // 4 blue
            "#C58BD9", // 5 magenta
            "#62C9BE", // 6 cyan
            "#C8CDBF", // 7 white
            "#2C3D34", // 8 bright black
            "#F08C93", // 9 bright red
            "#9BE564", // 10 bright green
            "#F0D89A", // 11 bright yellow
            "#8CB9EE", // 12 bright blue
            "#DDA8EC", // 13 bright magenta
            "#8EE0D6", // 14 bright cyan
            "#F4F1E8"  // 15 bright white
        ]
    )

    /// Its daylight counterpart.
    static let guacLight = TerminalTheme(
        id: "guac-light",
        name: "Guac Light",
        isLight: true,
        background: "#F7F4EA",
        foreground: "#17251E",
        cursor: "#4E8A2E",
        ansi: [
            "#1F2E27", // 0 black
            "#B3373A", // 1 red
            "#3F7D3A", // 2 green
            "#9A7326", // 3 yellow
            "#2E6FA8", // 4 blue
            "#8B4494", // 5 magenta
            "#1F7A72", // 6 cyan
            "#5A6B60", // 7 white
            "#4A5A52", // 8 bright black
            "#D25A54", // 9 bright red
            "#4E8A2E", // 10 bright green
            "#B8913A", // 11 bright yellow
            "#4A8AC9", // 12 bright blue
            "#A863B4", // 13 bright magenta
            "#35988E", // 14 bright cyan
            "#2B3A33"  // 15 bright white
        ]
    )

    // MARK: - Catalog

    /// Every theme the picker shows: the two signature themes first, then the
    /// vendored schemes sorted by name.
    ///
    /// Initialised once, lazily — the vendored list is ~230 KB of JSON, so it
    /// must not be re-parsed per access. If Resources/Themes.json is missing or
    /// unreadable, `ThemeCatalogLoader.themes` is empty, logs why, and the app
    /// keeps working with just the two signature themes.
    static let catalog: [TerminalTheme] = {
        let signature = [guac, guacLight]

        // The signature themes win any clash, so a vendored scheme can never
        // shadow "guac" (which must always sort first, as the default) and no
        // identifier or name appears twice.
        var seenIDs = Set(signature.map(\.id))
        var seenNames = Set(signature.map { $0.name.lowercased() })

        var merged = signature
        merged.reserveCapacity(signature.count + ThemeCatalogLoader.themes.count)

        for theme in ThemeCatalogLoader.themes {
            guard seenIDs.insert(theme.id).inserted,
                  seenNames.insert(theme.name.lowercased()).inserted
            else { continue }
            merged.append(theme)
        }

        return merged
    }()
}
